'use strict';

/* Imagens de contusão (sem rosto e sem uniforme). Preenchido quando as imagens chegarem: [{src:'data:image/jpeg;base64,...'}] */
const INJURY_IMGS = [{src:'data:image/webp;base64,'},{src:'data:image/webp;base64,'},{src:'data:image/webp;base64,'},{src:'data:image/webp;base64,'},{src:'data:image/webp;base64,'},{src:'data:image/webp;base64,'},{src:'data:image/webp;base64,'}];
function injCard(name, games) {
  const h = crestHash(name), im = INJURY_IMGS.length ? INJURY_IMGS[(Math.imul(h ^ (h >>> 15), 2246822507) >>> 0) % INJURY_IMGS.length] : null;
  return `<div class="injc">${im ? `<img src="${im.src}" alt="">` : `<div class="injph">🩹</div>`}<div class="injt"><small>${t('inj_title')}</small><b>${esc(name)}</b><span>${t('inj_out', { n: games })}</span></div></div>`;
}

/* Imagens dos eventos (id 1-8). Preencher com {src:'data:image/jpeg;base64,...'} quando chegarem. */
const EVENT_IMGS = {1:{src:'data:image/webp;base64,'},2:{src:'data:image/webp;base64,'},3:{src:'data:image/webp;base64,'},4:{src:'data:image/webp;base64,'},5:{src:'data:image/webp;base64,'},6:{src:'data:image/webp;base64,'},7:{src:'data:image/webp;base64,'},8:{src:'data:image/webp;base64,'}};
const EV_EMO = { 1: '🎪', 2: '💰', 3: '📺', 4: '🎉', 5: '🤝', 6: '🏕️', 7: '🧒', 8: '💼' };
function evHero(id) {
  const im = EVENT_IMGS[id];
  return `<div class="evh e${id}">${im ? `<img src="${im.src}" alt="">` : `<span>${EV_EMO[id] || '🏀'}</span>`}</div>`;
}

/* Ginásio (arena): imagem por nível 1-3. */
const FAC_IMGS = { gym:[{src:'data:image/webp;base64,'},{src:'data:image/webp;base64,'},{src:'data:image/webp;base64,'}],med:[{src:'data:image/webp;base64,'},{src:'data:image/webp;base64,'},{src:'data:image/webp;base64,'}],shop:[{src:'data:image/webp;base64,'},{src:'data:image/webp;base64,'},{src:'data:image/webp;base64,'}], arena: [{src:'data:image/webp;base64,'},{src:'data:image/webp;base64,'},{src:'data:image/webp;base64,'}] };
function facHero(k, l) { const a = FAC_IMGS[k]; if (!a) return ''; return `<div class="fach ${l ? '' : 'off'}"><img src="${a[Math.max(0, l - 1)].src}" alt=""><b>${'★'.repeat(l) || '🔒'}</b></div>`; }
